void bfs(int x,int y)
{
    memset(dis, -1, sizeof dis);
    queue<pii> q;
    dis[x][y]= 0;
    q.push({x,y});

    while(!q.empty())
    {
        x=  q.front().first;
        y=  q.front().second;

        q.pop();

        for(int j=0; j<4; j++)
        {
            int xx =x+dx[j];
            int yy =y+dy[j];

            if(xx<0 or xx>= n)
                continue;
            if(yy<0 or yy>= n)
                continue;

            if(dis[xx][yy] !=-1 )
                continue;

            if(t[xx][yy]=='Y' or t[xx][yy]=='Z')
                continue;
            dis[xx][yy]= dis[x][y]+1;
            q.push({xx,yy});
        }
    }
}

int dp[65][12][12][12][12];

int pos(int t,int x0,int y0, int x,int y)
{
    if(dis[x0][y0]< t) return 0;
    if(x0==x and y0==y) return 1;

    if(t>=k) return 0;

    if(dis[x0][y0]<=t) return 0;

    if(dp[t][x0][y0][x][y]!=-1) return dp[t][x0][y0][x][y];

    for(int j=0; j<4; j++)
    {
        int xx = x0+dx[j];
        int yy = y0+dy[j];

        if(xx<0 or xx>= n)
            continue;
        if(yy<0 or yy>= n)
            continue;
        if(s[xx][yy]=='Y') continue;
        if(s[xx][yy]=='Z') continue;

        if(pos(t+1 , xx ,yy , x , y)) return dp[t][x0][y0][x][y]=1;
    }
    return dp[t][x0][y0][x][y]=0;
}


